// server/services/dual-agent/session-plan.ts
//
// Session-plan enhancer: the prompt/section machinery behind the Monitor's
// thorough startup, restructured into three independently-cacheable GROUPS
// generated by four parallel LLM calls.
//
//   GROUP        CALLS                 SECTIONS
//   identity     identity_core         persona, gesture_overrides, safety_notes,
//                                      observer_instructions, board_manager_guidance
//                identity_examples     sentence_interpretation_examples,
//                                      board_manager_examples
//   situations   situations            speaker_interact_examples,
//                                      speaker_assist_examples
//   goals        goals                 session_goals
//
// Grouping follows input volatility, which is what makes caching work:
//   - identity depends ONLY on the student record + memory + clinician prompts
//     + AAC settings — it changes between sessions (wrap-up note updates,
//     clinician edits), never within a day on its own.
//   - situations additionally depends on the likely situation: weekday,
//     part of day, and the calendar-event schedule around the session. Most
//     events repeat weekly, so the same slot re-hits week after week; a
//     one-off event or an hour-by-hour class change alters the event
//     signature and forces a regenerate (see situationsHash).
//   - goals depends on TODAY: today's events, the student's current location,
//     and the part of day. Smallest output; cheapest to regenerate.
//
// The legacy interact_mode_examples / assist_mode_examples sections (consumed
// only by the single-agent Interactive prompt, which no live path uses) are
// intentionally NOT generated anymore — the legacy prompt builder falls back
// to its static examples. This alone removes the two largest output sections
// from the startup-critical LLM call.
//
// Each call's prompt carries only what its sections need: the speech-only and
// prose calls skip the ~1k-token symbol inventory + button-encoding rules that
// only the encoding-heavy example sections require.

import { createHash } from "crypto";
import { getBundledIconsBlock } from "../memory-schema/aac-memory-schema";
import { T } from "../memory-schema/canonical-terms";
import { getLanguageName } from "@shared/language-names";
import {
  languageLevelFromInt,
  languageLevelDirective,
  languageLevelExampleReplies,
  type LanguageLevel,
} from "@shared/aac-language-level";
import type { EnhancedPromptSections } from "./types";

// ---------------------------------------------------------------------------
// Section defang (moved from monitor-agent.ts so both it and this module can
// share it without a cycle)
// ---------------------------------------------------------------------------

/**
 * XML-style section names that wrap each enhanced section once embedded in
 * the live system prompt (e.g. `<persona>...</persona>`). If the enhancer's
 * output contains a literal closing tag for one of these, it would prematurely
 * close the wrapper and let subsequent content land as a sibling section.
 * Mirror of the list in aac-settings-memory-schema.ts; kept narrow to the
 * tags this layer actually emits.
 */
const SECTION_RESERVED_XML_TAGS = [
  "persona", "session_goals", "memory", "security", "student_safety",
  "student_specific_examples", "persona_gesture_override",
  "gesture_defaults", "role", "communication", "presence", "speakers",
  "observations", "board", "environment", "examples", "example",
  "bad_examples", "bad_example",
];
const SECTION_XML_DEFANG_PATTERN = new RegExp(
  `</?(?:${SECTION_RESERVED_XML_TAGS.join("|")})\\b[^>]*>`,
  "gi",
);

export function defangSectionContent(s: string): string {
  return s.replace(SECTION_XML_DEFANG_PATTERN, (m) =>
    m.replace(/[<>]/g, (c) => (c === "<" ? "(" : ")")),
  );
}

